const C = {"REELS":[{"x":-84,"name":"Retrovirus","n":5},{"x":-14,"name":"Sendai","n":4},{"x":56,"name":"mRNA","n":4}],"RR":27,"RY1":-92,"RZ":45,"DECK_H":8,"DECK":{"x":-118,"y":-116,"w":222,"d":98,"r":4},"READER":{"x":-112,"y":-42,"w":200,"d":16,"r":2},"COL_Y":18,"COL_W":22,"COL_MAX":44,"FINAL":[0.86,0.8,0.78],"TL":{"SPIN":[0.3,7.6],"COUNT":[0.9,7.4],"BENIGN":[8,9.4],"VERDICT":[9.4,10.2],"END":12.5},"P":{"origin":[300,239.78085307871007],"scale":1.1782358189133506,"azimuth":45,"elevation":30},"A":"#ffa070","E":"#ffcbb0","END":12.5};
