  glow(slot, idle ? 0.35 : u < TL.SPIN[1] ? 0.6 + 0.4 * Math.abs(Math.sin(u * 5)) : 0.35);
  const v = idle ? 0.25 : 0.25 + 0.75 * over(TL.VERDICT, u);
